$field = function ($label, $name, $input_type = 'text', $required = true, $attrs = '') { echo '<label class="form-field"><span>' . esc_html($label) . ($required ? '<i aria-label="필수">*</i>' : '<small>선택</small>') . '</span><input name="' . esc_attr($name) . '" type="' . esc_attr($input_type) . '" maxlength="200" ' . ($required ? 'required ' : '') . $attrs . '></label>'; };
$textarea = function ($label, $name, $required = false) { echo '<label class="form-field full"><span>' . esc_html($label) . ($required ? '<i aria-label="필수">*</i>' : '<small>선택</small>') . '</span><textarea name="' . esc_attr($name) . '" rows="5" maxlength="5000" ' . ($required ? 'required' : '') . '></textarea></label>'; };
$select = function ($label, $name, $options) { echo '<label class="form-field"><span>' . esc_html($label) . '<i aria-label="필수">*</i></span><select name="' . esc_attr($name) . '" required><option value="">선택해 주세요</option>'; foreach ($options as $value => $text) echo '<option value="' . esc_attr($value) . '">' . esc_html($text) . '</option>'; echo '</select></label>'; };
?>
<section class="section form-layout"><aside class="form-aside" data-reveal><h2>당신의 일상에<br><em>강진 한 권.</em></h2><?php if ($type === 'personal') { ?><div class="price-line"><span>낱권</span><b><?php echo !empty($settings['singlePrice']) ? esc_html(number_format((int) $settings['singlePrice']) . '원') : '운영자 확인 후 안내'; ?></b></div><div class="price-line"><span>연간 구독</span><b><?php echo !empty($settings['annualPrice']) ? esc_html(number_format((int) $settings['annualPrice']) . '원') : '운영자 확인 후 안내'; ?></b></div><?php } ?><p>신청·상담 접수 후 편집부에서 일정과 조건을 안내합니다. 이 양식은 계약·결제·구독 확정을 의미하지 않습니다.</p><div class="contact-info"><span>EDITORIAL OFFICE</span><a href="mailto:<?php echo esc_attr($settings['email']); ?>"><?php echo esc_html($settings['email']); ?></a></div><div class="form-links"><?php foreach (array('subscription' => '구독 안내','refund' => '취소·환불 안내','privacy' => '개인정보 처리방침') as $key => $label) echo '<a href="' . esc_url(mg_theme_url('policies/' . $key . '/')) . '">' . esc_html($label) . '</a>'; ?></div></aside><div class="form-panel"><h2><?php echo esc_html(array('personal' => '정기 구독 신청','institution' => '기관 구독 상담','advertising' => '광고·협업 상담','contact' => '문의 보내기')[$type]); ?></h2><p class="form-required">* 표시는 필수 항목입니다.</p><?php if (!function_exists('mg_receive_inquiry')) echo '<p class="form-notice static-notice">접수 서비스가 연결되지 않았습니다. 실제 문의는 편집부 이메일로 보내주세요.</p>'; else echo '<p class="form-notice">개인정보 동의 후 접수하면 편집부에서 확인 후 연락드립니다.</p>'; ?><form class="inquiry-form" data-inquiry="<?php echo esc_attr($type); ?>" data-contact-email="<?php echo esc_attr($settings['email']); ?>"><div class="form-fields"><?php
