if ($type === 'personal') { $field('구독 시작 희망 월', 'startMonth', 'month'); $textarea('남기실 말씀', 'notes'); }
if ($type === 'institution') { $field('매월 희망 부수', 'copies', 'number', true, 'min="1" max="10000" step="1"'); $select('구독 기간', 'duration', array('6' => '6개월','12' => '12개월','24' => '24개월')); echo '<label class="checkbox full"><input type="checkbox" name="quotation"> 견적서 발행을 요청합니다.</label>'; $textarea('요청 사항', 'notes'); }
if ($type === 'advertising') { $select('광고 유형', 'adType', array('print' => '지면 광고','online' => '온라인 광고','branded' => '브랜드 콘텐츠','other' => '기타 협업')); $select('예산 범위', 'budget', array('undecided' => '상담 후 결정','under-500k' => '50만원 미만','500k-1m' => '50만~100만원','1m-3m' => '100만~300만원','over-3m' => '300만원 이상')); $textarea('광고 내용·희망 일정', 'message', true); }
if ($type === 'contact') $textarea('문의 내용', 'message', true);
